<script setup>
import {ref,computed,getCurrentInstance,onUnmounted} from 'vue'
import {onLoad,onShow} from '@dcloudio/uni-app'
import AppNavBar from '../../components/AppNavBar.vue'
import CloudMealPurchase from '../../components/CloudMealPurchase.vue'
import {openerChannel} from '../../services/address-navigation.js'
import {storageContext} from '../../services/storage.js'
import {getSession} from '../../services/session.js'
import {request} from '../../services/request.js'
import {purchaseGroups,referencePurchaseFor,mealLabels,mealOrder} from '../../services/meal-workspace.js'
import {formalRoute} from '../../services/meal-detail-client.js'
const instance=getCurrentInstance(),owner=storageContext(),plan=ref(null),error=ref(''),index=ref(0),orders=ref({}),checkout=ref(false),purchase=ref(null),loading=ref(false)
let alive=true,target=null,ticket=0
const groups=computed(()=>plan.value?purchaseGroups(plan.value):[]),current=computed(()=>groups.value[index.value]),missing=computed(()=>mealOrder.filter(t=>!groups.value.some(g=>g.purchaseMeals.includes(t))))
function leave(){if(purchase.value?.isBusy)return;if(checkout.value){purchase.value?.closeCheckout();checkout.value=false;return}uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/chat/index'})})}
async function load(){const mine=++ticket;loading.value=true;error.value='';try{const {data}=await request({path:'/api/family/'+encodeURIComponent(getSession().householdId)+'/daily-meal-plans/'+target.date});if(!alive||mine!==ticket||owner!==storageContext())return;if(data.date!==target.date||data.status!=='ready'||data.version!==target.version)throw Error('今日餐单已更新，请返回重新打开。');plan.value=data}catch(e){if(alive&&mine===ticket)error.value=e.message}finally{if(alive&&mine===ticket)loading.value=false}}
function ordered(sn){orders.value={...orders.value,[index.value]:sn};checkout.value=false}
function viewOrder(sn){uni.navigateTo({url:'/pages/orders/detail?id='+encodeURIComponent(sn)})}
function select(i){if(purchase.value?.isBusy||i===index.value)return;index.value=i;checkout.value=false}
onLoad(()=>openerChannel(instance)?.on('mealWorkspace',value=>{if(owner!==storageContext()||value.owner!==owner)return;target=value.target;void load()}))
onShow(()=>{if(owner!==storageContext()){plan.value=null;error.value='账号或家庭已变化，请重新打开';return}if(target&&plan.value){void load();void purchase.value?.refresh()}})
onUnmounted(()=>{alive=false;ticket++})
</script>
<template><view class="all-purchase-page" :class="{'is-checkout':checkout}"><AppNavBar><view class="all-nav"><button :aria-label="checkout?'返回食材选择':'返回今日餐单'" :disabled="purchase?.isBusy" @click="leave">‹</button><text>{{checkout?'确认采购订单':'全天食材'}}</text></view></AppNavBar><view v-if="loading&&!plan" class="all-status">正在读取今日餐单…</view><view v-else-if="error" class="all-status" role="alert"><text>{{error}}</text><button @click="load">重新读取</button></view><template v-else-if="plan"><view class="all-intro"><text v-if="!checkout" class="all-title">一天所需，一起准备</text><text class="all-notice">{{groups.length>1?'共 '+groups.length+' 个采购包，分别核价、确认下单。配送费按各单计算。':'核对食材、收货地址与配送费后再确认下单。'}}</text><text v-if="missing.length" class="all-warning">{{missing.map(t=>mealLabels[t]).join('、')}}暂无可购买食材，未包含在本次采购中。</text></view><scroll-view scroll-x :show-scrollbar="false" class="all-tabs"><view class="all-tab-row"><button v-for="(group,i) in groups" :key="i" :class="{active:index===i,done:orders[i]}" :disabled="purchase?.isBusy" @click="select(i)">{{group.label}} {{orders[i]?'已下单':'· '+(i+1)}}</button></view></scroll-view><view v-if="current" class="all-content"><view v-if="orders[index]" class="all-result"><text class="result-icon">✓</text><text>本采购包已下单</text><text class="all-notice">请进入订单支付；其他采购包需要分别确认。</text><button @click="viewOrder(orders[index])">查看订单并支付</button><button v-if="index<groups.length-1" class="next-purchase" @click="select(index+1)">继续核对{{groups[index+1].label}}</button><button v-else class="next-purchase" @click="leave">返回今日餐单</button></view><CloudMealPurchase v-else ref="purchase" :key="current.sourceId+index" embedded managed :meal="{...current.seed,members:current.purchaseMembers}" :route="formalRoute(current)" :reference="referencePurchaseFor(current)" @checkout="checkout=$event" @ordered="ordered"/></view><view v-else class="all-status">今天还没有可购买的食材。</view></template><view v-else class="all-status">请从今日餐单的“一键购买”进入。</view></view></template>
<style scoped>
.all-purchase-page{height:100vh;height:100dvh;max-width:480px;margin:auto;display:flex;flex-direction:column;box-sizing:border-box;background:var(--ui-canvas-gradient);color:var(--ui-text);padding-top:8px}.all-purchase-page>:deep(.app-nav){padding:0 20px}.all-nav{display:flex;align-items:center;gap:12px;min-height:48px}.all-nav>text{font-size:19px;font-weight:600}.all-nav button{display:flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;margin:0 0 0 -10px;padding:0;background:transparent;font-size:30px;color:var(--ui-accent)}.all-intro{padding:18px 22px 12px}.all-title{display:block;font-size:23px;font-weight:600;line-height:1.5}.all-notice{display:block;font-size:12px;color:var(--ui-muted);line-height:1.8;margin-top:8px}.all-warning{display:block;font-size:12px;color:#a37f53;line-height:1.7;margin-top:8px}.all-tabs{width:100%;white-space:nowrap;flex-shrink:0}.all-tabs .all-tab-row{display:flex;gap:8px;padding:4px 20px 12px}.all-tabs button{width:auto;flex-shrink:0;margin:0;padding:10px 15px;min-height:44px;border-radius:99px;border:1px solid #fff;background:rgba(255,255,255,.7);box-shadow:inset 0 1px 1px #fff;font-size:13px;color:var(--ui-muted);white-space:nowrap}.all-tabs button.active{background:var(--ui-accent-soft);border-color:var(--ui-accent);color:var(--ui-accent)}.all-tabs button.done{color:#708163}.all-content{height:0;flex:1;min-height:0;display:flex;flex-direction:column}.all-result{margin:24px;padding:30px 22px;background:var(--ui-bubble);border:1px solid #fff;border-radius:28px;text-align:center;box-shadow:0 5px 25px rgba(66,40,85,.04)}.all-result>text{display:block}.result-icon{font-size:36px;color:#8da278;margin-bottom:18px}.all-result button{margin-top:24px;min-height:48px;border-radius:99px;background:var(--ui-accent);color:#fff;font-size:15px}.all-result .next-purchase{background:var(--ui-accent-soft);color:var(--ui-accent)}.all-status{padding:48px 24px;font-size:14px;line-height:1.8;color:var(--ui-muted)}.all-status button{margin-top:20px;color:var(--ui-accent)}button:after{border:0}
</style>

<style scoped>.is-checkout .all-intro{padding-top:0;padding-bottom:8px}.is-checkout .all-notice{margin-top:0}</style>
